INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 13, 'theory', 'Quiz: indexes and EXPLAIN');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 13, 0, 'What does SCAN mean in an EXPLAIN QUERY PLAN output?', '["A lookup through an index", "A full pass over the table", "Scanning the disk for errors", "Sorting the result"]', 1, 'SCAN means the database reads the table row by row. SEARCH … USING INDEX means a jump through an index to the needed rows.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 13, 1, 'An index is created on (customer_id, created). Which condition uses it worst?', '["WHERE customer_id = 5", "WHERE customer_id = 5 AND created > ''2024-05-01''", "WHERE created > ''2024-05-01''", "WHERE customer_id IN (1, 2)"]', 2, 'The leftmost prefix rule: an index on (a, b) is effective when the condition uses a, or a and b. On b alone it means a scan.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 13, 2, 'Why does WHERE UPPER(name) = ''IVAN'' not use an ordinary index on name?', '["UPPER is not allowed in WHERE", "A function on a column takes away the database''s ability to search the ordered values", "An index only works with numbers", "The name is too short"]', 1, 'The index stores the values of name, not UPPER(name). The fix is an index on the expression UPPER(name), or a condition where the column stands on its own.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 13, 3, 'What is a covering index?', '["An index on all columns of the table", "An index that contains all the columns the query needs, so the table need not be read", "An index with a uniqueness check", "A temporary index"]', 1, 'If all the requested columns are in the index, the database takes the values straight from it (USING COVERING INDEX).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 13, 4, 'Which column is almost pointless to index?', '["email (unique)", "customer_id in a foreign key", "vip with values 0 and 1", "created (order date)"]', 2, 'Low selectivity: the condition returns half of the table, and scanning every row is cheaper than jumping through the index.');
